mapper.select:
SELECT PATH
  FROM (
        SELECT PROFILE_IMAGE_PATH AS PATH FROM USERS WHERE USER_ID = #{userId}
        UNION
        SELECT PROFILE_ORIGINAL_IMAGE_PATH AS PATH FROM USERS WHERE USER_ID = #{userId}
        UNION
        SELECT CROPPED_IMAGE_PATH AS PATH FROM USER_PROFILE_IMAGES WHERE USER_ID = #{userId}
        UNION
        SELECT ORIGINAL_IMAGE_PATH AS PATH FROM USER_PROFILE_IMAGES WHERE USER_ID = #{userId}
       )
 WHERE PATH IS NOT NULL

